3-4ca9-9e89-8f92076a668b","vaultid":"d495f853-af54-4cea-9e68-a9454624c682","type":"mcq","answerOptions":[{"id":"01347b8e-2da9-4981-9a74-4560fba1dd4e","content":"<p><math alttext=\"100\"><mn>100</mn>\n</math></p>"},{"id":"278818c9-b44a-47c3-92db-c3b8702cf98e","content":"<p><math alttext=\"125\"><mn>125</mn>\n</math></p>"},{"id":"9d64e25b-e3bc-4d77-a870-a0a83516887d","content":"<p><math alttext=\"175\"><mn>175</mn>\n</math></p>"},{"id":"aa1f3ec1-f9aa-445c-9c39-45787a4e613d","content":"<p><math alttext=\"225\"><mn>225</mn>\n</math></p>"}],"correct_answer":["C"]},"createDate":1691007959811,"updateDate":1691007959811}$SATQ$::jsonb, 1691007959811, 1691007959811),
    ($SATQ$72a5fd28$SATQ$, $SATQ$784ebc69-0579-465e-9969-ad19889a3bd4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.E.$SATQ$, $SATQ$Linear inequalities in one or two variables$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$spr$SATQ$, NULL, $SATQ$<p style="text-align: left;">For a party, <math alttext="50"><mn>50</mn>
</math> dinner rolls are needed. Dinner rolls are sold in packages of <math alttext="12"><mn>12</mn>
</math>. What is the minimum number of packages that should be bought for the party?</p>$SATQ$, $SATQ$[]$SATQ$::jsonb, $SATQ$["5"]$SATQ$::jsonb, $SATQ$["5"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">The correct answer is <math alttext="5"><mn>5</mn>
</math>. Let <math alttext="p"><mi>p</mi>
</math> represent the number of packages of dinner rolls that should be bought for the party. It's given that dinner rolls are sold in packages of <math alttext="12"><mn>12</mn>
</math>. Therefore, <math alttext="12 p"><mrow>
	<mn>12</mn>
	<mi>p</mi>
</mrow>
</math> represents the number of dinner rolls that should be bought for the party. It's also given that <math alttext="50"><mn>50</mn>
</math> dinner rolls are needed; therefore, <math alttext="12 p greater than or equals 50"><mn>12</mn><mi>p</mi><mo>&#8805;</mo><mn>50</mn></math>. Dividing both sides of this inequality by <math alttext="12"><mn>12</mn>
</math> yields <math alttext="p greater than or equals StartFraction 50 Over 12 EndFraction"><mi>p</mi><mo>&#8805;</mo><mfrac><mn>50</mn><mn>12</mn></mfrac></math>, or approximately <math alttext="p greater than or equals 4.17"><mi>p</mi><mo>&#8805;</mo><mn>4.17</mn></math>. Since the number of packages of dinner rolls must be a whole number, the minimum number of packages that should be bought for the party is <math alttext="5"><mn>5</mn>
</math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"72a5fd28","external_id":"784ebc69-0579-465e-9969-ad19889a3bd4","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"7073f2d5-ac34-4f5c-818b-307a5461afe0","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"H","domain":"Algebra","skill_cd":"H.E.","skill_desc":"Linear inequalities in one or two variables","difficulty":"E","score_band_range_cd":3,"type":"spr","stimulus":null,"stem":"<p style=\"text-align: left;\">For a party, <math alttext=\"50\"><mn>50</mn>\n</math> dinner rolls are needed. Dinner rolls are sold in packages of <math alttext=\"12\"><mn>12</mn>\n</math>. What is the minimum number of packages that should be bought for the party?</p>","answerOptions":[],"keys":["5"],"correct_answer":["5"],"rationale":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"5\"><mn>5</mn>\n</math>. Let <math alttext=\"p\"><mi>p</mi>\n</math> represent the number of packages of dinner rolls that should be bought for the party. It's given that dinner rolls are sold in packages of <math alttext=\"12\"><mn>12</mn>\n</math>. Therefore, <math alttext=\"12 p\"><mrow>\n\t<mn>12</mn>\n\t<mi>p</mi>\n</mrow>\n</math> represents the number of dinner rolls that should be bought for the party. It's also given that <math alttext=\"50\"><mn>50</mn>\n</math> dinner rolls are needed; therefore, <math alttext=\"12 p greater than or equals 50\"><mn>12</mn><mi>p</mi><mo>&#8805;</mo><mn>50</mn></math>. Dividing both sides of this inequality by <math alttext=\"12\"><mn>12</mn>\n</math> yields <math alttext=\"p greater than or equals StartFraction 50 Over 12 EndFraction\"><mi>p</mi><mo>&#8805;</mo><mfrac><mn>50</mn><mn>12</mn></mfrac></math>, or approximately <math alttext=\"p greater than or equals 4.17\"><mi>p</mi><mo>&#8805;</mo><mn>4.17</mn></math>. Since the number of packages of dinner rolls must be a whole number, the minimum number of packages t