mo>+</mo><mrow><mn>35</mn></mrow></mrow></mfenced></math></p>"},{"id":"867c7bb5-2772-44d7-b4c1-74d4e5d11c31","content":"<p><math alttext=\"left parenthesis minus StartFraction 3 r Over 2 EndFraction plus seven halves comma r right parenthesis\"><mfenced><mrow><mo>-</mo><mfrac><mrow><mrow><mn>3</mn></mrow><mi>r</mi></mrow><mrow><mn>2</mn></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>7</mn></mrow><mrow><mn>2</mn></mrow></mfrac><mo>,</mo><mo>&#160;</mo><mi>r</mi></mrow></mfenced></math></p>"},{"id":"b25ad3f1-96ef-4518-ac99-6f57429d78ac","content":"<p><math alttext=\"left parenthesis r comma StartFraction 2 r Over 3 EndFraction plus seven thirds right parenthesis\"><mfenced><mrow><mi>r</mi><mo>,</mo><mo>&#160;</mo><mfrac><mrow><mrow><mn>2</mn></mrow><mi>r</mi></mrow><mrow><mn>3</mn></mrow></mfrac><mo>+</mo><mrow><mfrac><mn>7</mn><mn>3</mn></mfrac></mrow></mrow></mfenced></math></p>"},{"id":"9371e6ef-1066-41f4-abeb-df5ceef295f4","content":"<p><math alttext=\"left parenthesis r comma minus StartFraction 3 r Over 2 EndFraction plus seven halves right parenthesis\"><mfenced><mrow><mi>r</mi><mo>,</mo><mo>-</mo><mfrac><mrow><mrow><mn>3</mn></mrow><mi>r</mi></mrow><mrow><mn>2</mn></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>7</mn></mrow><mrow><mn>2</mn></mrow></mfrac></mrow></mfenced></math></p>"}],"correct_answer":["B"]},"createDate":1691007959818,"updateDate":1691007959818}$SATQ$::jsonb, 1691007959818, 1691007959818),
    ($SATQ$7625073d$SATQ$, $SATQ$6b671d8f-d733-464f-b0d9-9d825d5fd66c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.C.$SATQ$, $SATQ$Linear equations in two variables$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$spr$SATQ$, NULL, $SATQ$<p style="text-align: left;">The equation <math alttext="7 g plus 7 b equals 840"><mrow>
	<mrow>
		<mrow>
			<mn>7</mn>
			<mi>g</mi>
		</mrow>
		<mo>+</mo>
		<mrow>
			<mn>7</mn>
			<mi>b</mi>
		</mrow>
	</mrow>
	<mo>=</mo>
	<mn>840</mn>
</mrow>
</math> represents the number of blue tiles, <math alttext="b"><mi>b</mi>
</math>, and the number of green tiles, <math alttext="g"><mi>g</mi>
</math>, an artist needs for an <math alttext="840"><mn>840</mn>
</math>-square-inch tile project. The artist needs <math alttext="71"><mn>71</mn>
</math> blue tiles for the project. How many green tiles does he need?</p>$SATQ$, NULL, $SATQ$["49"]$SATQ$::jsonb, $SATQ$["49"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">The correct answer is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="49"><mn>49</mn></math>. It’s given that the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="7 g plus 7 b equals 840"><mn>7</mn><mi>g</mi><mo>+</mo><mn>7</mn><mi>b</mi><mo>=</mo><mn>840</mn></math> represents the number of blue tiles, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b"><mi>b</mi></math>, and the number of green tiles, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="g"><mi>g</mi></math>, an artist needs for an <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="840"><mn>840</mn></math>-square-inch tile project. It’s also given that the artist needs <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="71"><mn>71</mn></math> blue tiles for the project. Substituting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="71"><mn>71</mn></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b"><mi>b</mi></math> in the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="7 g plus 7 b equals 840"><mn>7</mn><mi>g</mi><mo>+</mo><mn>7</mn><mi>b</mi><mo>=</mo><mn>840</mn></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="7 g plus 7 left parenthesis 71 right parenthesis equals 840"><mn>7</mn><mi>g</mi><mo>+</mo><mn>7</mn><mo>(</mo><mn>71</mn><mo>)</mo><mo>=</mo><mn>840</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="7 g plus 497 equals 840"><mn>7</mn><mi>g</mi><mo>+</mo><mn>497</mn><mo>=</mo><mn>840</mn></math>. Subtracting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="497"><mn>497</mn></math> from both sides of this equation yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="7 g equals 343"><mn>7</mn><mi>g</mi><mo>=</mo><mn>343</mn></math>. Dividing both sid